"""Portable research reports built only from immutable saved run artifacts."""
import csv
import io
import json
import re
import zipfile
from html import escape
from pathlib import Path


def safe_json(value):
    raw = json.dumps(value, ensure_ascii=True, allow_nan=False, separators=(',', ':'))
    return raw.replace('&', '\\u0026').replace('<', '\\u003c').replace('>', '\\u003e')


def csv_data(rows, fields=None):
    output = io.StringIO(newline='')
    fields = fields or list(dict.fromkeys(key for row in rows for key in row))
    if not fields:
        return ''
    writer = csv.DictWriter(output, fieldnames=fields, extrasaction='ignore')
    writer.writeheader()
    for row in rows:
        # Prevent spreadsheet formula evaluation of user-controlled strings.
        writer.writerow({key: "'" + value if isinstance(value, str) and value.lstrip().startswith(('=', '+', '-', '@')) else value for key, value in row.items()})
    return output.getvalue()


def html_report(run, analyses, manifest=None):
    bundle = Path(__file__).resolve().parents[1] / 'node_modules' / 'plotly.js-dist-min' / 'plotly.min.js'
    plotly = re.sub(r'</script', r'<\\/script', bundle.read_text(encoding='utf-8'), flags=re.I)
    payload = safe_json({'report_version': 1, 'run': run, 'analyses': analyses, 'dataset': manifest})
    quality = run.get('data_quality')
    info = quality if quality is not None else (manifest or {}).get('repair_info')
    count = int((info or {}).get('proxy_bars', 0))
    context = 'Run interval' if quality is not None else 'Dataset'
    notice = (f'<p class="notice" id="data-quality">{context}: {count:,} candles use adjusted reference OHLC and estimated volume, not observed Delta trades. Sparse early trading and changing venue basis make some adjustments uncertain. Original Delta rows are unchanged.</p>' if count else '')
    ratio_notice = ('<p class="notice" id="ratio-contract">Ratio brackets use absolute price levels, not percentage moves. 1R = quantity × initial entry-to-stop distance. Planned risk/reward is frozen at entry. Realized R includes actual fills and fees; gaps can exceed 1R loss. End-of-test exits are incomplete brackets. Win rate is measured, never guaranteed.</p>' if run.get('config', {}).get('exit_mode') == 'risk_reward' else '')
    return TEMPLATE.replace('__TITLE__', escape(run.get('config', {}).get('name', 'Strategy report'))).replace('__DATA_QUALITY__', notice + ratio_notice + (f'<p class="notice" id="skipped-entries">{len(run.get("skipped_entries", [])):,} {"entry" if len(run["skipped_entries"]) == 1 else "entries"} skipped because price or slippage crossed a valid signal-close stop/target before entry. No fees were charged and levels were not moved. Exact rejected signals are retained in the embedded research JSON and the ZIP skipped-entries.csv.</p>' if run.get('skipped_entries') else '')).replace('__PLOTLY__', plotly).replace('__PAYLOAD__', payload)


def research_package(run, analyses, manifest=None):
    output = io.BytesIO()
    config = run.get('config', {})
    with zipfile.ZipFile(output, 'w', compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('report.html', html_report(run, analyses, manifest))
        archive.writestr('run.json', json.dumps(run, indent=2, allow_nan=False))
        archive.writestr('analyses.json', json.dumps(analyses, indent=2, allow_nan=False))
        archive.writestr('dataset-manifest.json', json.dumps(manifest, indent=2, allow_nan=False))
        quality = run.get('data_quality') or (manifest or {}).get('repair_info')
        if quality:
            archive.writestr('data-quality.json', json.dumps(quality, indent=2, allow_nan=False))
        archive.writestr('strategy-config.json', json.dumps(config, indent=2, allow_nan=False))
        archive.writestr('trades.csv', csv_data(run.get('trades', [])))
        if run.get('skipped_entries'):
            archive.writestr('skipped-entries.csv', csv_data(run['skipped_entries']))
        archive.writestr('equity.csv', csv_data(run.get('equity', [])))
        archive.writestr('cash-ledger.csv', csv_data(run.get('ledger', [])))
        if config.get('strategy') == 'python':
            archive.writestr('strategy.py', config.get('code', ''))
        archive.writestr('README.txt', 'Noctra local research package\n\nOpen report.html in a browser; it works offline and can print to PDF.\nThe report embeds the complete saved run and all available saved analyses.\nCharts may sample long series for display; JSON and CSV retain all records.\nTrade tables are paginated; choose Show all trades before printing the full ledger.\nDataset metadata identifies source candles; source candle Parquet files are not included.\nOnly analyses already saved for this run are included. Missing analyses were not fabricated or automatically run.\nLeverage is a notional/equity cap, with sizing determined by the saved execution mode and contract rounding; exchange margin/liquidation and funding cashflows are not modeled.\n')
    return output.getvalue()


